self.by_node = {}
self.fragmented_nodes = set()
for i, node in enumerate(self.layout["nodeIndex"]):
    require(integer(node) and 0 <= node < count,
            "SNAPSHOT_LAYOUT_OWNER", "Invalid raw layout owner.")
    if node in self.fragmented_nodes:
        continue
    if node in self.by_node:
        # Keep no chosen row for a fragmented owner, even identical rows.
        self.fragmented_nodes.add(node)
        del self.by_node[node]
    else:
        self.by_node[node] = i

